-- Migration: 008_seed_formula_templates.up.sql
-- Service: xstockstrat-indicators
-- feature 335: data only. Seeds the system formula templates; created_by = 'system' rows are read-only
-- through ManageTemplate. Row grammar is fixed (four dollar-quoted literals per row) and parsed by tests.

INSERT INTO indicators.formula_templates (template_id, name, description, payload, created_by)
VALUES
  ($t$tpl-volatility_trailing_stop_direction$t$, $t$Volatility Trailing Stop Direction$t$, $t$Chandelier/SuperTrend-style trailing stop computed on close (volatility proxy = rolling mean absolute close change). value = +1 while price holds above the ratcheting long stop, -1 below the short stop; flips only when price crosses the stop line, resisting whipsaw. Rules: exit longs on vts crosses_below 0. Secondary series 'stop_line' returned for charting/standalone runs.$t$, $t${"name": "Volatility Trailing Stop Direction", "description": "Chandelier/SuperTrend-style trailing stop computed on close (volatility proxy = rolling mean absolute close change). value = +1 while price holds above the ratcheting long stop, -1 below the short stop; flips only when price crosses the stop line, resisting whipsaw. Rules: exit longs on vts crosses_below 0. Secondary series 'stop_line' returned for charting/standalone runs.", "source": "import numpy as np\n\nclose = np.asarray(data[\"close\"], dtype=float)\np = int(params[\"period\"])\nmult = float(params[\"multiplier\"])\nn = len(close)\n\nout = [None] * n\nline = [None] * n\nif n > p:\n    diffs = np.abs(np.diff(close))\n    direction = 1\n    atr0 = diffs[:p].mean()\n    stop = close[p] - mult * atr0\n    out[p] = 1.0\n    line[p] = float(stop)\n    for i in range(p + 1, n):\n        atr = diffs[i - p : i].mean()\n        if direction == 1:\n            stop = max(stop, close[i] - mult * atr)\n            if close[i] < stop:\n                direction = -1\n                stop = close[i] + mult * atr\n        else:\n            stop = min(stop, close[i] + mult * atr)\n            if close[i] > stop:\n                direction = 1\n                stop = close[i] - mult * atr\n        out[i] = float(direction)\n        line[i] = float(stop)\n\nresult = {\"value\": out, \"stop_line\": line}", "parameters": [{"name": "period", "type": "PARAMETER_TYPE_INT", "defaultValue": 22.0, "description": "Volatility lookback in bars", "min": 5.0, "max": 100.0}, {"name": "multiplier", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 3.0, "description": "Volatility multiple for the stop distance", "min": 0.5, "max": 10.0}]}$t$::jsonb, 'system'),
  ($t$tpl-bollinger_squeeze_percentile$t$, $t$Bollinger Squeeze Percentile$t$, $t$Volatility-compression detector: percentile rank (0..1) of the current Bollinger bandwidth ((2*std)/mean over 'period') within the trailing 'lookback' window. Low values = squeeze (energy building); a rise back through ~0.25 marks the squeeze release/breakout. Rules: entry sqz crosses_above 0.25 combined with a momentum sign filter (e.g. macd.histogram > 0). Secondary series 'bandwidth' returned for standalone runs.$t$, $t${"name": "Bollinger Squeeze Percentile", "description": "Volatility-compression detector: percentile rank (0..1) of the current Bollinger bandwidth ((2*std)/mean over 'period') within the trailing 'lookback' window. Low values = squeeze (energy building); a rise back through ~0.25 marks the squeeze release/breakout. Rules: entry sqz crosses_above 0.25 combined with a momentum sign filter (e.g. macd.histogram > 0). Secondary series 'bandwidth' returned for standalone runs.", "source": "import numpy as np\n\nclose = np.asarray(data[\"close\"], dtype=float)\np = int(params[\"period\"])\nlb = int(params[\"lookback\"])\nn = len(close)\n\nbw = [None] * n\nfor i in range(p - 1, n):\n    w = close[i - p + 1 : i + 1]\n    m = w.mean()\n    bw[i] = float(2.0 * w.std() / m) if m > 0 else 0.0\n\nout = [None] * n\nfor i in range(p - 1, n):\n    start = max(p - 1, i - lb + 1)\n    window = [b for b in bw[start : i + 1] if b is not None]\n    if len(window) >= 20:\n        out[i] = float(sum(1 for b in window if b <= bw[i]) / len(window))\n\nresult = {\"value\": out, \"bandwidth\": bw}", "parameters": [{"name": "period", "type": "PARAMETER_TYPE_INT", "defaultValue": 20.0, "description": "Bollinger window in bars for the bandwidth", "min": 5.0, "max": 100.0}, {"name": "lookback", "type": "PARAMETER_TYPE_INT", "defaultValue": 120.0, "description": "Trailing window for the percentile rank", "min": 30.0, "max": 500.0}]}$t$::jsonb, 'system'),
  ($t$tpl-fundamentals_value_quality_composite_template$t$, $t$Fundamentals Value+Quality Composite (template)$t$, $t$Per-symbol value+quality composite over fundamental metrics. Value sub-score blends P/E, P/B and a triangular dividend-yield band; quality sub-score blends ROE, D/E and EPS sign. Missing metrics drop out neutrally. Band endpoints and weights are tunable formula params (no deploy needed to retune). Requires analysis.backtest.fundamentals.enabled to be on; otherwise it reads hold.$t$, $t${"name": "Fundamentals Value+Quality Composite (template)", "description": "Per-symbol value+quality composite over fundamental metrics. Value sub-score blends P/E, P/B and a triangular dividend-yield band; quality sub-score blends ROE, D/E and EPS sign. Missing metrics drop out neutrally. Band endpoints and weights are tunable formula params (no deploy needed to retune). Requires analysis.backtest.fundamentals.enabled to be on; otherwise it reads hold.", "source": "\ndef _get(key):\n    v = data.get(key)\n    if v is None:\n        return None\n    try:\n        return float(v)\n    except (TypeError, ValueError):\n        return None\n\n\ndef _clamp(x):\n    if x < 0.0:\n        return 0.0\n    if x > 1.0:\n        return 1.0\n    return x\n\n\ndef _lin(x, good, bad):\n    # Linear band to [0,1]. good < bad => lower-is-better; good > bad => higher-is-better.\n    if good == bad:\n        return 1.0\n    if good < bad:\n        if x <= good:\n            return 1.0\n        if x >= bad:\n            return 0.0\n        return (bad - x) / (bad - good)\n    else:\n        if x >= good:\n            return 1.0\n        if x <= bad:\n            return 0.0\n        return (x - bad) / (good - bad)\n\n\ndef _p(name, default):\n    v = params.get(name)\n    return float(v) if v is not None else default\n\n\nvalue_weight = _p(\"value_weight\", 0.5)\nquality_weight = _p(\"quality_weight\", 0.5)\n\n# \u2500\u2500 Value sub-score: P/E, P/B, dividend-yield (triangular) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nvalue_parts = []\n\npe = _get(\"pe_ratio\")\nif pe is not None:\n    # FR-4: non-positive P/E (loss-making) scores 0.\n    value_parts.append(0.0 if pe <= 0 else _lin(pe, _p(\"pe_good\", 10.0), _p(\"pe_bad\", 35.0)))\n\npb = _get(\"pb_ratio\")\nif pb is not None:\n    # FR-4: negative book value scores 0.\n    value_parts.append(0.0 if pb < 0 else _lin(pb, _p(\"pb_good\", 1.0), _p(\"pb_bad\", 5.0)))\n\ndy = _get(\"dividend_yield\")\nif dy is not None:\n    peak = _p(\"div_peak\", 0.04)\n    zero_hi = _p(\"div_zero_hi\", 0.10)\n    if dy <= 0:\n        div_score = 0.0\n    elif dy <= peak:\n        div_score = dy / peak if peak > 0 else 0.0\n    elif dy >= zero_hi:\n        div_score = 0.0\n    else:\n        div_score = (zero_hi - dy) / (zero_hi - peak)\n    value_parts.append(_clamp(div_score))\n\nvalue_sub = sum(value_parts) / len(value_parts) if value_parts else 0.5\n\n# \u2500\u2500 Quality sub-score: ROE, D/E, EPS sign \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nquality_parts = []\n\nroe = _get(\"roe\")\nif roe is not None:\n    quality_parts.append(_lin(roe, _p(\"roe_good\", 0.25), _p(\"roe_bad\", 0.05)))\n\nde = _get(\"debt_to_equity\")\nif de is not None:\n    # FR-4: negative equity scores 0.\n    quality_parts.append(0.0 if de < 0 else _lin(de, _p(\"de_good\", 0.3), _p(\"de_bad\", 2.0)))\n\neps = _get(\"eps\")\nif eps is not None:\n    quality_parts.append(1.0 if eps > 0 else 0.0)\n\nquality_sub = sum(quality_parts) / len(quality_parts) if quality_parts else 0.5\n\nvalue_sub = _clamp(value_sub)\nquality_sub = _clamp(quality_sub)\ncomposite = _clamp(value_weight * value_sub + quality_weight * quality_sub)\n\nresult = {\"value\": value_sub, \"quality\": quality_sub, \"composite\": composite}\n", "parameters": [{"name": "value_weight", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 0.5, "description": "Weight of the value sub-score in the composite"}, {"name": "quality_weight", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 0.5, "description": "Weight of the quality sub-score in the composite"}, {"name": "pe_good", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 10.0, "description": "P/E at or below which the P/E score is 1.0 (Graham value floor)"}, {"name": "pe_bad", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 35.0, "description": "P/E at or above which the P/E score is 0.0"}, {"name": "pb_good", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 1.0, "description": "P/B at or below which the P/B score is 1.0"}, {"name": "pb_bad", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 5.0, "description": "P/B at or above which the P/B score is 0.0"}, {"name": "div_peak", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 0.04, "description": "Dividend yield at which the yield score peaks at 1.0"}, {"name": "div_zero_hi", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 0.1, "description": "Dividend yield at or above which the yield score returns to 0.0 (trap guard)"}, {"name": "roe_good", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 0.25, "description": "ROE at or above which the ROE score is 1.0"}, {"name": "roe_bad", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 0.05, "description": "ROE at or below which the ROE score is 0.0"}, {"name": "de_good", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 0.3, "description": "Debt/Equity at or below which the D/E score is 1.0"}, {"name": "de_bad", "type": "PARAMETER_TYPE_FLOAT", "defaultValue": 2.0, "description": "Debt/Equity at or above which the D/E score is 0.0"}], "outputs": [{"name": "quality", "description": "Quality sub-score in [0,1]"}, {"name": "composite", "description": "Weighted value+quality composite in [0,1]"}], "fundamentalInputs": ["FUNDAMENTAL_METRIC_PE_RATIO", "FUNDAMENTAL_METRIC_PB_RATIO", "FUNDAMENTAL_METRIC_DIVIDEND_YIELD", "FUNDAMENTAL_METRIC_ROE", "FUNDAMENTAL_METRIC_DEBT_TO_EQUITY", "FUNDAMENTAL_METRIC_EPS"]}$t$::jsonb, 'system'),
  ($t$tpl-sma_trend_slope_fractional$t$, $t$SMA Trend Slope (fractional)$t$, $t$Fractional slope of the SMA(period) over the last `lookback` bars: (sma[i] - sma[i-lookback]) / |sma[i-lookback]|. Positive = the moving average is rising (risk-on regime), negative = rolling over. Scale-free so a >0 gate works across price levels. Intended as a per-symbol broad-trend regime filter for dip-buy strategies.$t$, $t${"name": "SMA Trend Slope (fractional)", "description": "Fractional slope of the SMA(period) over the last `lookback` bars: (sma[i] - sma[i-lookback]) / |sma[i-lookback]|. Positive = the moving average is rising (risk-on regime), negative = rolling over. Scale-free so a >0 gate works across price levels. Intended as a per-symbol broad-trend regime filter for dip-buy strategies.", "source": "import numpy as np\n\nclose = np.asarray(data[\"close\"], dtype=float)\np = int(params[\"period\"])\nlb = int(params[\"lookback\"])\nn = len(close)\n\nsma = [None] * n\nfor i in range(p - 1, n):\n    sma[i] = float(close[i - p + 1 : i + 1].mean())\n\nout = [None] * n\nfor i in range(p - 1 + lb, n):\n    prev = sma[i - lb]\n    if prev is not None and prev != 0:\n        out[i] = float((sma[i] - prev) / abs(prev))\n\nresult = {\"value\": out}\n", "parameters": [{"name": "period", "type": "PARAMETER_TYPE_INT", "defaultValue": 200.0, "description": "SMA window in bars", "required": true, "min": 20.0, "max": 400.0}, {"name": "lookback", "type": "PARAMETER_TYPE_INT", "defaultValue": 20.0, "description": "Bars back over which the slope is measured", "required": true, "min": 1.0, "max": 200.0}], "warmupPeriod": 220}$t$::jsonb, 'system'),
  ($t$tpl-momentum_quality_clenow$t$, $t$Momentum Quality (Clenow)$t$, $t$Andreas Clenow's momentum-quality score: annualized exponential regression slope of log(close) over 'period' bars, multiplied by the regression R-squared. Rewards steady, persistent trends and punishes gappy/erratic ones. Rules: entry mq > 0.3 (roughly a smooth +30% annualized trend); also a strong cross-sectional ranking metric for screening a watchlist.$t$, $t${"name": "Momentum Quality (Clenow)", "description": "Andreas Clenow's momentum-quality score: annualized exponential regression slope of log(close) over 'period' bars, multiplied by the regression R-squared. Rewards steady, persistent trends and punishes gappy/erratic ones. Rules: entry mq > 0.3 (roughly a smooth +30% annualized trend); also a strong cross-sectional ranking metric for screening a watchlist.", "source": "import numpy as np\n\nclose = np.asarray(data[\"close\"], dtype=float)\np = int(params[\"period\"])\nn = len(close)\n\nout = [None] * n\nx = np.arange(p, dtype=float)\nfor i in range(p - 1, n):\n    y = np.log(np.clip(close[i - p + 1 : i + 1], 1e-9, None))\n    slope, intercept = np.polyfit(x, y, 1)\n    yhat = slope * x + intercept\n    ss_tot = float(((y - y.mean()) ** 2).sum())\n    r2 = 1.0 - float(((y - yhat) ** 2).sum()) / ss_tot if ss_tot > 0 else 0.0\n    annualized = float(np.exp(slope * 252.0) - 1.0)\n    out[i] = float(annualized * r2)\n\nresult = {\"value\": out}", "parameters": [{"name": "period", "type": "PARAMETER_TYPE_INT", "defaultValue": 90.0, "description": "Regression lookback in bars", "min": 20.0, "max": 250.0}]}$t$::jsonb, 'system'),
  ($t$tpl-kaufman_efficiency_ratio$t$, $t$Kaufman Efficiency Ratio$t$, $t$Kaufman's Efficiency Ratio (trend-strength regime filter, 0..1): net directional move over the period divided by the sum of absolute bar-to-bar moves. Near 1 = clean trend, near 0 = chop. Rules: er > 0.3 gates trend-following entries; er < 0.15 gates mean-reversion entries.$t$, $t${"name": "Kaufman Efficiency Ratio", "description": "Kaufman's Efficiency Ratio (trend-strength regime filter, 0..1): net directional move over the period divided by the sum of absolute bar-to-bar moves. Near 1 = clean trend, near 0 = chop. Rules: er > 0.3 gates trend-following entries; er < 0.15 gates mean-reversion entries.", "source": "import numpy as np\n\nclose = np.asarray(data[\"close\"], dtype=float)\np = int(params[\"period\"])\nn = len(close)\n\nout = [None] * n\nfor i in range(p, n):\n    net = abs(close[i] - close[i - p])\n    path = np.abs(np.diff(close[i - p : i + 1])).sum()\n    out[i] = float(net / path) if path > 0 else 0.0\n\nresult = {\"value\": out}", "parameters": [{"name": "period", "type": "PARAMETER_TYPE_INT", "defaultValue": 10.0, "description": "Lookback in bars for the efficiency calculation", "min": 2.0, "max": 100.0}]}$t$::jsonb, 'system'),
  ($t$tpl-mean_reversion_z_score$t$, $t$Mean-Reversion Z-Score$t$, $t$Z-score of close vs rolling mean in rolling-std units. value[i] = (close[i] - mean(period)) / std(period). Use in rules: entry z < -2 (stretched below), exit z crosses_above 0 (reverted). Also useful as a cross-sectional screener metric for ranking watchlist symbols by stretch.$t$, $t${"name": "Mean-Reversion Z-Score", "description": "Z-score of close vs rolling mean in rolling-std units. value[i] = (close[i] - mean(period)) / std(period). Use in rules: entry z < -2 (stretched below), exit z crosses_above 0 (reverted). Also useful as a cross-sectional screener metric for ranking watchlist symbols by stretch.", "source": "import numpy as np\n\nclose = np.asarray(data[\"close\"], dtype=float)\np = int(params[\"period\"])\nn = len(close)\n\nout = [None] * n\nfor i in range(p - 1, n):\n    w = close[i - p + 1 : i + 1]\n    s = w.std()\n    out[i] = float((close[i] - w.mean()) / s) if s > 0 else 0.0\n\nresult = {\"value\": out}", "parameters": [{"name": "period", "type": "PARAMETER_TYPE_INT", "defaultValue": 20.0, "description": "Rolling window length in bars for mean/std", "min": 5.0, "max": 250.0}]}$t$::jsonb, 'system'),
  ($t$tpl-rolling_zscore_v2$t$, $t$rolling_zscore_v2$t$, $t$$t$, $t${"name": "rolling_zscore_v2", "source": "import pandas as pd\nclose = pd.Series(data[\"close\"])\nwindow = params[\"window\"]\nmean = close.rolling(window).mean()\nstd = close.rolling(window).std()\nz = (close - mean) / std\nresult = {\"value\": [None if (pd.isna(v) or v in (float(\"inf\"), float(\"-inf\"))) else v for v in z]}\n", "parameters": [{"name": "window", "type": "PARAMETER_TYPE_INT", "defaultValue": 20.0, "description": "Rolling window (bars) for mean/std", "min": 2.0, "max": 500.0}]}$t$::jsonb, 'system'),
  ($t$tpl-kaufman_efficiency_ratio_v2$t$, $t$kaufman_efficiency_ratio_v2$t$, $t$$t$, $t${"name": "kaufman_efficiency_ratio_v2", "source": "import pandas as pd\nclose = pd.Series(data[\"close\"])\nwindow = params[\"window\"]\nchange = (close - close.shift(window)).abs()\nvolatility = close.diff().abs().rolling(window).sum()\ner = change / volatility\nresult = {\"value\": [None if (pd.isna(v) or v in (float(\"inf\"), float(\"-inf\"))) else v for v in er]}\n", "parameters": [{"name": "window", "type": "PARAMETER_TYPE_INT", "defaultValue": 10.0, "description": "Lookback window (bars) for Kaufman efficiency ratio", "min": 2.0, "max": 500.0}]}$t$::jsonb, 'system')
ON CONFLICT (template_id) DO NOTHING;

DO $$
DECLARE held TEXT;
BEGIN
  SELECT string_agg(template_id, ', ' ORDER BY template_id) INTO held
    FROM indicators.formula_templates
   WHERE template_id IN (
    'tpl-volatility_trailing_stop_direction',
    'tpl-bollinger_squeeze_percentile',
    'tpl-fundamentals_value_quality_composite_template',
    'tpl-sma_trend_slope_fractional',
    'tpl-momentum_quality_clenow',
    'tpl-kaufman_efficiency_ratio',
    'tpl-mean_reversion_z_score',
    'tpl-rolling_zscore_v2',
    'tpl-kaufman_efficiency_ratio_v2'
   ) AND created_by <> 'system';
  IF held IS NOT NULL THEN
    RAISE EXCEPTION 'indicators seed_formula_templates: seeded template_id held by a non-system row: %', held;
  END IF;
END $$;
